// logo returns an inline SVG of the Dogmatiq logo, with the given class.
func logo(class string) template.HTML {
	return template.HTML(
		`<svg class="` + template.HTMLEscapeString(class) + `" viewBox="` + logoViewBox +
			`" aria-hidden="true"><path fill-rule="evenodd" d="` + logoPath + `"/></svg>`,
	)
}
